=head2 Google::Cloud::Tpu::V2alpha1::CloudTpu::Reservation

A reservation describes the amount of a resource 'allotted' for a defined
period of time.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The reservation name with the format:
projects/{projectID}/locations/{location}/reservations/{reservationID}

=item * C<< $msg->standard() >> / C<< $msg->standard($value) >>

Type: C<Message> (L<Google::Cloud::Tpu::V2alpha1::CloudTpu::Reservation::Standard>)

A standard reservation.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Tpu::V2alpha1::Reservation::State>)

Output only. The state of the Reservation.

=back

=head3 Enum: Reservation::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<APPROVED> => C<3>

=item * C<PROVISIONING> => C<4>

=item * C<ACTIVE> => C<5>

=item * C<DEPROVISIONING> => C<6>

=item * C<EXPIRED> => C<7>

=item * C<FAILED> => C<8>

=back

