=head2 Google::Cloud::Tpu::V2alpha1::CloudTpu::CustomerEncryptionKey

Customer's encryption key.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->kms_key_name() >> / C<< $msg->kms_key_name($value) >>

Type: C<String>

The name of the encryption key that is stored in Google Cloud KMS.
For example:
<pre class="lang-html">"kmsKeyName": "projects/
<var class="apiparam">kms_project_id</var>/locations/
<var class="apiparam">region</var>/keyRings/<var class="apiparam">
key_region</var>/cryptoKeys/<var class="apiparam">key</var>
</pre>
The fully-qualifed key name may be returned for resource GET requests.
For example:
<pre class="lang-html">"kmsKeyName": "projects/
<var class="apiparam">kms_project_id</var>/locations/
<var class="apiparam">region</var>/keyRings/<var class="apiparam">
key_region</var>/cryptoKeys/<var class="apiparam">key</var>
/cryptoKeyVersions/1</pre>

=back

=head2 Google::Cloud::Tpu::V2alpha1::CloudTpu::UpcomingMaintenance

Upcoming Maintenance notification information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Tpu::V2alpha1::UpcomingMaintenance::MaintenanceType>)

Defines the type of maintenance.

=item * C<< $msg->can_reschedule() >> / C<< $msg->can_reschedule($value) >>

Type: C<Bool>

Indicates if the maintenance can be customer triggered.

=item * C<< $msg->window_start_time() >> / C<< $msg->window_start_time($value) >>

Type: C<String>

The current start time of the maintenance window.
This timestamp value is in RFC3339 text format.

=item * C<< $msg->window_end_time() >> / C<< $msg->window_end_time($value) >>

Type: C<String>

The time by which the maintenance disruption will be completed.
This timestamp value is in RFC3339 text format.

=item * C<< $msg->latest_window_start_time() >> / C<< $msg->latest_window_start_time($value) >>

Type: C<String>

The latest time for the planned maintenance window to start.
This timestamp value is in RFC3339 text format.

=item * C<< $msg->maintenance_status() >> / C<< $msg->maintenance_status($value) >>

Type: C<Enum> (L<Google::Cloud::Tpu::V2alpha1::UpcomingMaintenance::MaintenanceStatus>)

The status of the maintenance.

=back

=head3 Enum: UpcomingMaintenance::MaintenanceType

=over 4

=item * C<UNKNOWN_TYPE> => C<0>

=item * C<SCHEDULED> => C<1>

=item * C<UNSCHEDULED> => C<2>

=back

=head3 Enum: UpcomingMaintenance::MaintenanceStatus

=over 4

=item * C<UNKNOWN> => C<0>

=item * C<PENDING> => C<1>

=item * C<ONGOING> => C<2>

=back

